package com.booksyde.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="marketplace_orders",schema="public")
public class MarketplaceOrderEntity { @Id private UUID id; @Column(name="buyer_id",nullable=false) private UUID buyerId; @Column(name="seller_id",nullable=false) private UUID sellerId; @Column(nullable=false) private String status; @Column(name="total_cents",nullable=false) private int totalCents; @Column(nullable=false) private String currency; @Column(name="stripe_environment",nullable=false) private String stripeEnvironment; @Column(name="stripe_account_id") private String stripeAccountId; @Column(name="checkout_session_id") private String checkoutSessionId; @Column(name="checkout_url") private String checkoutUrl; @Column(name="paid_at") private OffsetDateTime paidAt; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; protected MarketplaceOrderEntity(){} public UUID getId(){return id;} public UUID getBuyerId(){return buyerId;} public UUID getSellerId(){return sellerId;} public String getStatus(){return status;} public int getTotalCents(){return totalCents;} public String getCurrency(){return currency;} public String getStripeEnvironment(){return stripeEnvironment;} public String getStripeAccountId(){return stripeAccountId;} public String getCheckoutSessionId(){return checkoutSessionId;} public String getCheckoutUrl(){return checkoutUrl;} public OffsetDateTime getPaidAt(){return paidAt;} public OffsetDateTime getCreatedAt(){return createdAt;} public void markAwaitingPayment(String sessionId,String url,String accountId){status="awaiting_payment";checkoutSessionId=sessionId;checkoutUrl=url;stripeAccountId=accountId;} public void markPaid(){status="paid";paidAt=OffsetDateTime.now();} }
